const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laJolla = ee.Geometry.Point([-117.274, 32.847]).buffer(10000); // 10km buffer
  const baseDate = '2018-08-01';
  const date2018 = ee.Date(baseDate);
  const date2017 = date2018.advance(-1, 'year');

  // Function to get SST composite for a given date and window
  function getSSTComposite(targetDate, windowDays) {
    const start = targetDate.advance(-windowDays / 2, 'day');
    const end = targetDate.advance(windowDays / 2, 'day');
    const col = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
      .filterBounds(laJolla)
      .filterDate(start, end)
      .select(['sst', 'land']);
    return col;
  }

  // Try increasing windows if no data
  const windows = [3, 7, 30];
  let sst2018 = null;
  let sst2017 = null;
  let images2018 = 0;
  let images2017 = 0;

  for (const win of windows) {
    const col2018 = getSSTComposite(date2018, win);
    const col2017 = getSSTComposite(date2017, win);

    if (sst2018 === null) {
      const size2018 = col2018.size().getInfo();
      if (size2018 > 0) {
        // Take median composite and mask land (land=0 is water)
        const composite2018 = col2018.median();
        const waterMask = composite2018.select('land').eq(0);
        sst2018 = composite2018.select('sst').updateMask(waterMask);
        images2018 = size2018;
      }
    }

    if (sst2017 === null) {
      const size2017 = col2017.size().getInfo();
      if (size2017 > 0) {
        const composite2017 = col2017.median();
        const waterMask = composite2017.select('land').eq(0);
        sst2017 = composite2017.select('sst').updateMask(waterMask);
        images2017 = size2017;
      }
    }

    if (sst2018 && sst2017) break;
  }

  // Check for empty collections
  if (!sst2018 || !sst2017) {
    console.log(`2018 Images: ${images2018}, 2017 Images: ${images2017}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get mean SST and valid pixel counts
  const scale = 4000; // MODIS resolution ~4km
  const stats2018 = sst2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: laJolla,
    scale: scale,
    maxPixels: 1e9,
  });
  const stats2017 = sst2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: laJolla,
    scale: scale,
    maxPixels: 1e9,
  });

  const mean2018 = stats2018.get('sst').getInfo();
  const count2018 = stats2018.get('sst_count').getInfo();
  const mean2017 = stats2017.get('sst').getInfo();
  const count2017 = stats2017.get('sst_count').getInfo();

  // Check for no valid pixels
  if (count2018 === 0 || count2017 === 0) {
    console.log(`2018 Pixels: ${count2018}, 2017 Pixels: ${count2017}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // Validate SST range (reasonable ocean temps near California)
  const validRange = [-2, 40];
  if (mean2018 === null || mean2017 === null ||
      mean2018 < validRange[0] || mean2018 > validRange[1] ||
      mean2017 < validRange[0] || mean2017 > validRange[1]) {
    console.log(`2018 SST: ${mean2018}, 2017 SST: ${mean2017}`);
    console.log('<answer>C3</answer>');
    return;
  }

  // Output stats and final answer
  console.log(`2018 Images: ${images2018} (SST: ${mean2018.toFixed(2)}°C, Pixels: ${count2018})`);
  console.log(`2017 Images: ${images2017} (SST: ${mean2017.toFixed(2)}°C, Pixels: ${count2017})`);

  if (mean2018 > mean2017) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
